// What the orchestrator asked of each delegation and what came of it: the DESIGN block its prompt
// opened with (the dispatch-contract skill, parsed in design.ts), kept beside the agent's outcome, and four predicates
// that question a delegation. Each predicate is written once, in flagsOf; pure, so the register and
// the tests share it.

import type { AgentRecord, DelegationFlag, DelegationRow, DelegationStats, TurnRecord } from '../types'
import { familyOf } from './models'
import { eventsBySession, judge } from './outcome'

export const OVERKILL_STEPS = 5 // source: own choice, an opus or fable agent that took at most this many steps did a small job
export const UNDERPOWERED_RATE = 0.25 // source: own choice, a flag on one small delegation, not a decision: one failed call in four (the old phase threshold; phases are now read with intervals, hooks/rungs.ts)
export const UNDERPOWERED_MIN_STEPS = 4 // source: own choice, fewer steps than this is too small a sample for a failure rate
export const RECENT_FLAGGED = 8 // source: own choice, the flagged delegations the panel can list

const FLAGS: readonly DelegationFlag[] = ['undesigned', 'rerouted', 'overkill', 'underpowered']

const REAL = new Set(['haiku', 'sonnet', 'opus', 'fable'])

// The four predicates, the only place each concept is defined:
//  - undesigned:   the prompt carried no DESIGN block (design === null). A record kept before the
//                  design was (design absent) is legacy: no flag.
//  - rerouted:     the design names a model of a real family, the model that ran is of a real family,
//                  and the two families differ (the autopilot may lower a model under quota pressure).
//  - overkill:     the model that ran is opus or fable and the agent took at most OVERKILL_STEPS steps.
//  - underpowered: the model that ran is haiku, it took at least UNDERPOWERED_MIN_STEPS steps and
//                  errors / steps >= UNDERPOWERED_RATE.
export const flagsOf = (r: AgentRecord): DelegationFlag[] => {
  const flags: DelegationFlag[] = []
  const ran = familyOf(r.model)
  if (r.design === null) flags.push('undesigned')
  const wanted = r.design?.model == null ? null : familyOf(r.design.model)
  if (wanted !== null && REAL.has(wanted) && REAL.has(ran) && wanted !== ran) flags.push('rerouted')
  if ((ran === 'opus' || ran === 'fable') && r.steps <= OVERKILL_STEPS) flags.push('overkill')
  if (ran === 'haiku' && r.steps >= UNDERPOWERED_MIN_STEPS && r.errors / r.steps >= UNDERPOWERED_RATE) flags.push('underpowered')
  return flags
}

export const emptyDelegations = (): DelegationStats => ({
  total: 0,
  designed: 0,
  outcomes: { achieved: 0, 'not-achieved': 0, unclear: 0 },
  rounds: 0,
  flags: { overkill: 0, underpowered: 0, undesigned: 0, rerouted: 0 },
  recent: [],
})

// One delegation is one agentId: a resumed agent writes a record per turn, summed here and judged
// once. A record without agentId (legacy) is its own delegation.
type Delegation = { agent: AgentRecord; at: number; session: string }

const delegationsOf = (records: readonly TurnRecord[]): Delegation[] => {
  const out: Delegation[] = []
  const byId = new Map<string, Delegation>()
  for (const rec of records) {
    for (const a of rec.agents) {
      const seen = a.agentId === undefined ? undefined : byId.get(a.agentId)
      if (seen === undefined) {
        const d = { agent: { ...a }, at: rec.at, session: rec.session }
        out.push(d)
        if (a.agentId !== undefined) byId.set(a.agentId, d)
        continue
      }
      const s = seen.agent
      s.steps += a.steps
      s.errors += a.errors
      if (a.tokensIn !== undefined) s.tokensIn = (s.tokensIn ?? 0) + a.tokensIn
      if (a.tokensOut !== undefined) s.tokensOut = (s.tokensOut ?? 0) + a.tokensOut
      if (s.design === undefined && a.design !== undefined) s.design = a.design
      s.model = a.model
      seen.at = rec.at
    }
  }
  return out
}

// Every delegation: `total` counts those that have a design field (null included), `designed` those
// whose design is not null, `flags` each flag over the delegation's summed steps and errors, `recent`
// the last RECENT_FLAGGED flagged rows, newest last. O(agents).
export const delegationStats = (records: readonly TurnRecord[]): DelegationStats => {
  const stats = emptyDelegations()
  const events = eventsBySession(records)
  for (const { agent: a, at, session } of delegationsOf(records)) {
    if (a.design === undefined) continue
    stats.total += 1
    if (a.design !== null) stats.designed += 1
    // The outcome the session's events show for this delegation; a legacy record (no agentId) has none to join.
    const joined = events.get(session)
    const judged = a.agentId === undefined ? undefined : judge(joined?.own ?? [], a.agentId, joined?.foreign)
    if (judged !== undefined) {
      stats.outcomes[judged.verdict] += 1
      stats.rounds += judged.rounds
    } else stats.outcomes.unclear += 1
    const flags = flagsOf(a)
    if (flags.length === 0) continue
    for (const f of FLAGS) if (flags.includes(f)) stats.flags[f] += 1
    const row: DelegationRow = {
      at,
      type: a.type,
      model: a.model,
      effort: a.design?.effort ?? null,
      shape: a.design?.shape ?? null,
      steps: a.steps,
      errors: a.errors,
      flags,
      ...(judged === undefined ? {} : { outcome: judged.verdict }),
    }
    stats.recent.push(row)
    if (stats.recent.length > RECENT_FLAGGED) stats.recent.shift()
  }
  return stats
}

files.hooks/design.ts:
// The DESIGN block an orchestrator opens a subagent's prompt with (the dispatch-contract skill): the one parser of it.
// Shared, byte-identical, by zetetic-insights (which keeps the block beside the delegation's outcome) and
// zetetic-autopilot (which applies its model and effort at the spawn): scripts/check-shared.sh keeps the copies equal.
// Pure and self-contained: a mod cannot import a file from another mod.

export type DesignBlock = { model: string | null; effort: string | null; shape: string | null }

export const DESIGN_FIELD_CAP = 80 // source: own choice, characters kept of each design field; the block states a reason, not an essay

const cap = (s: string): string | null => {
  const t = s.trim().slice(0, DESIGN_FIELD_CAP)
  return t === '' ? null : t
}

// The DESIGN block of a prompt: the lines after the first line that is exactly `DESIGN`, up to the
// first blank line. `model: X` and `effort: Y` may share a line, separated by ` · `; `genius shape:`
// takes the rest of its line. A field the block does not state is null; no block is null. Total.
export const parseDesign = (prompt: string): DesignBlock | null => {
  if (typeof prompt !== 'string') return null
  const lines = prompt.split(/\r?\n/)
  const start = lines.findIndex((l) => l.trim() === 'DESIGN')
  if (start < 0) return null
  const design: DesignBlock = { model: null, effort: null, shape: null }
  for (const raw of lines.slice(start + 1)) {
    const line = raw.trim()
    if (line === '') break
    const shape = /^genius shape:(.*)$/i.exec(line)
    if (shape !== null) {
      design.shape ??= cap(shape[1] ?? '')
      continue
    }
    if (/^(task|check):/i.test(line)) continue
    for (const part of line.split(' · ')) {
      const m = /^(model|effort):(.*)$/i.exec(part.trim())
      if (m === null) continue
      const key = m[1]?.toLowerCase() === 'model' ? 'model' : 'effort'
      design[key] ??= cap(m[2] ?? '')
    }
  }
  return design
}

files.hooks/effect.ts:
// What an applied move did. Pure. A move of a phase's effort is credited only with a comparison of the
// same phase, the same task classes and the same population before and after it: the steps its ceiling
// decided (hooks/reach.ts: graded base at least the move's reach, not stuck-escalated, not under pressure),
// the runs of the rung left, then of the rung moved to. The pre statistics are frozen into the move when it
// is made, so trimming the ledger never discards them, and a phase's last move is never trimmed from the
// file; the post statistics are frozen when a later move of the same phase supersedes it. The difference carries its Newcombe interval (hooks/stats.ts).

import type { Calibration, Credit, DeltaInterval, Effect, Effort, Move, Phase, Proposal, Snapshot, Verdict } from '../types'
import { governs } from './reach'
import { type Cell } from './rungs'
import { newcombe } from './stats'

export const MOVES_CAP = 50 // source: own choice, the moves kept in the calibration file (~1 KB each): a phase moves a few times a week at most
const KEY_LENGTH = 8 // source: own choice, characters of a session id kept in a snapshot (the ids are UUIDs: 8 hex digits are unique enough within one ledger)

const key = (session: string): string => session.slice(0, KEY_LENGTH)

// The runs of `phase` at `effort` in `cells` that a move from `from` to `to` governs, as a snapshot; each
// session's outcome as given.
export const snapshotOf = (cells: readonly Cell[], outcomes: ReadonlyMap<string, Verdict>, phase: Phase, effort: string, from: Effort, to: Effort): Snapshot => {
  const snap: Snapshot = { byClass: {}, sessions: {} }
  for (const c of cells) {
    if (c.phase !== phase || c.effort !== effort || !governs(c, from, to)) continue
    const row = snap.byClass[c.taskClass] ?? { steps: 0, errors: 0 }
    snap.byClass[c.taskClass] = { steps: row.steps + c.steps, errors: row.errors + c.errors }
    snap.sessions[key(c.session)] = outcomes.get(c.session) ?? 'unclear'
  }
  return snap
}

const emptySnapshot = (): Snapshot => ({ byClass: {}, sessions: {} })

// The move made now: pre is the phase's runs at the rung left, up to now. The previous move of the same
// phase, if still open, is closed with the runs it governed since.
export const movesWith = (c: Calibration, ps: readonly Proposal[], at: number, cells: readonly Cell[], outcomes: ReadonlyMap<string, Verdict>): Move[] => {
  const moves = c.moves.map((m) => (m.post === null && ps.some((p) => p.phase === m.phase) ? { ...m, post: snapshotOf(cells.filter((x) => x.at > m.at), outcomes, m.phase, m.to, m.from, m.to) } : m))
  const added = ps.map((p) => ({ phase: p.phase, at, from: p.from, to: p.to, pre: snapshotOf(cells.filter((x) => x.at <= at), outcomes, p.phase, p.from, p.from, p.to), post: null }))
  return trimmed([...moves, ...added])
}

// The newest MOVES_CAP moves, except that the last move of each phase is kept whatever its age: it is the
// one the phase's undo is held to, and its `changes` entry stays in the file, so trimming it would make it
// read as a 0.8.x move with no baseline (movesOf). Eight phases at most, so the cap is still a bound.
const trimmed = (moves: readonly Move[]): Move[] => {
  const last = new Set(Object.values(Object.fromEntries(moves.map((m, i) => [m.phase, i]))))
  let excess = moves.length - MOVES_CAP
  return moves.filter((_, i) => {
    if (excess <= 0 || last.has(i)) return true
    excess -= 1
    return false
  })
}

type Side = Effect['preSide']

// One side's totals over the shared classes, and its judged / achieved sessions outside `drop` (the sessions on both sides).
const sideOf = (s: Snapshot, shared: ReadonlySet<string>, drop: ReadonlySet<string>): Side => {
  const side = { steps: 0, errors: 0, judged: 0, achieved: 0 }
  for (const [k, row] of Object.entries(s.byClass)) {
    if (!shared.has(k)) continue
    side.steps += row.steps
    side.errors += row.errors
  }
  for (const [k, o] of Object.entries(s.sessions)) {
    if (drop.has(k) || (o !== 'achieved' && o !== 'not-achieved')) continue
    side.judged += 1
    if (o === 'achieved') side.achieved += 1
  }
  return side
}

const creditOf = (failed: DeltaInterval, outcome: DeltaInterval | null, pre: Side, post: Side, baseline: boolean): Credit => {
  if (!baseline) return 'no-baseline'
  if (pre.steps === 0 || post.steps === 0) return 'insufficient'
  const harm = failed.lo > 0 || (outcome !== null && outcome.hi < 0)
  const benefit = failed.hi < 0 || (outcome !== null && outcome.lo > 0)
  return harm ? 'harm' : benefit ? 'benefit' : 'inconclusive'
}

// The effect of one move. `post` is the move's own frozen post when it has one, else the runs since it
// at the rung moved to. Sessions with runs on both sides of the move are left out of the outcome
// comparison (their outcome belongs to neither side), the failed-call comparison is on the shared classes.
export const effectOf = (m: Move, cells: readonly Cell[], outcomes: ReadonlyMap<string, Verdict>): Effect => {
  const post = m.post ?? snapshotOf(cells.filter((x) => x.at > m.at), outcomes, m.phase, m.to, m.from, m.to)
  const shared = new Set(Object.keys(m.pre.byClass).filter((k) => k in post.byClass))
  const both = new Set(Object.keys(m.pre.sessions).filter((k) => k in post.sessions))
  const preSide = sideOf(m.pre, shared, both)
  const postSide = sideOf(post, shared, both)
  const failed = newcombe({ k: postSide.errors, n: postSide.steps }, { k: preSide.errors, n: preSide.steps })
  const outcome = preSide.judged > 0 && postSide.judged > 0 ? newcombe({ k: postSide.achieved, n: postSide.judged }, { k: preSide.achieved, n: preSide.judged }) : null
  return { phase: m.phase, at: m.at, from: m.from, to: m.to, classes: [...shared].sort(), preSide, postSide, failed, outcome, credit: creditOf(failed, outcome, preSide, postSide, Object.values(m.pre.byClass).some((row) => row.steps > 0)) }
}

// The moves a calibration holds: those it recorded, and, for a phase whose last change has no recorded move
// (made under 0.8.x, whose file kept `changes` and no `moves`), a move with no pre statistics. Such a move
// is credited `no-baseline` (nothing was frozen when it was made), so it is neither protected from being
// undone nor unmeasured forever: the rung evidence decides, as for any proposal. Not written back: the next
// move of the phase replaces its `changes` entry.
export const movesOf = (c: Calibration): Move[] => [
  ...c.moves,
  ...Object.entries(c.changes).flatMap(([phase, ch]) => (ch === undefined || c.moves.some((m) => m.phase === phase && m.at === ch.at) ? [] : [emptyMove(phase as Phase, ch.at, ch.from, ch.to)])),
]

// The effect of each move, and the credit of each phase's last move (what undoing it is held to).
export const effectsOf = (moves: readonly Move[], cells: readonly Cell[], outcomes: ReadonlyMap<string, Verdict>): { effects: Effect[]; credits: Map<Phase, Credit> } => {
  const effects = moves.map((m) => effectOf(m, cells, outcomes))
  const credits = new Map<Phase, Credit>()
  for (const e of effects) credits.set(e.phase, e.credit)
  return { effects, credits }
}

const signed = (x: number): string => `${x >= 0 ? '+' : ''}${Math.round(100 * x)}`

// One line for the brief and /calibrate: the delta in points with its interval and the steps behind it.
export const effectLine = (e: Effect): string => {
  const failed = `failed calls ${signed(e.failed.d)} pts [${signed(e.failed.lo)}, ${signed(e.failed.hi)}] (${e.preSide.steps} -> ${e.postSide.steps} steps)`
  const outcome = e.outcome === null ? '' : `, sessions achieved ${signed(e.outcome.d)} pts [${signed(e.outcome.lo)}, ${signed(e.outcome.hi)}] (${e.preSide.judged} -> ${e.postSide.judged})`
  return `${e.phase} ${e.from} -> ${e.to}: ${failed}${outcome}; ${e.credit}`
}

export const emptyMove = (phase: Phase, at: number, from: Effort, to: Effort): Move => ({ phase, at, from, to, pre: emptySnapshot(), post: null })

