// The learning curve of each phase: main's failed-call rate over the ledger's turns, in order, and
// where the calibration moved the phase. What the mission-control pane draws; bounded, so the
// state it rides in stays small whatever the ledger holds.

import type { Calibration, Phase, PhaseTrend, TurnRecord } from '../types'

export const TREND_TURNS = 400 // source: own choice, the most recent turns a curve is drawn from
export const TREND_POINTS = 40 // source: own choice, the points of one curve (a pane is ~80 cells)

// Each phase's turns, newest TREND_TURNS, cut into at most TREND_POINTS consecutive buckets of
// equal size; a point is a bucket's errors over its steps. O(records), at most 8 × 40 points.
export const trends = (records: readonly TurnRecord[], changes: Calibration['changes']): PhaseTrend[] => {
  const by = new Map<Phase, { at: number; steps: number; errors: number }[]>()
  for (const r of records.slice(-TREND_TURNS))
    for (const run of r.main) {
      const rows = by.get(run.phase) ?? []
      const last = rows[rows.length - 1]
      if (last !== undefined && last.at === r.at) {
        last.steps += run.steps
        last.errors += run.errors
      } else rows.push({ at: r.at, steps: run.steps, errors: run.errors })
      by.set(run.phase, rows)
    }
  return [...by.entries()]
    .map(([phase, turns]) => {
      const size = Math.ceil(turns.length / TREND_POINTS)
      const points = []
      for (let i = 0; i < turns.length; i += size) {
        const bucket = turns.slice(i, i + size)
        const steps = bucket.reduce((n, t) => n + t.steps, 0)
        const errors = bucket.reduce((n, t) => n + t.errors, 0)
        points.push({ at: bucket[bucket.length - 1]!.at, steps, rate: steps === 0 ? 0 : errors / steps })
      }
      const move = changes[phase]
      return { phase, points, move: move === undefined ? null : { at: move.at, from: move.from, to: move.to } }
    })
    .sort((a, b) => a.phase.localeCompare(b.phase))
}

files.hooks/events.ts:
// What a Bash tool call shows about the fate of the work, read live at `tool.call` (no transcript):
// a commit, a revert, a test run and its exit status, a push, a pull request created, reviewed,
// merged or closed. Pure and total: any command and result go in, the closed list of events comes
// out, nothing throws. The command text is the primary source; the Bash result's structured
// `gitOperation` (claude-code-tools Bash output) corroborates it and names the sha and the PR number
// when the command does not. Where each event comes from, and what it cannot tell, is written in
// docs/insights-outcome-model.md.

import type { EventSource, FrictionKind, LiveFriction, OutcomeEvent } from '../types'
import { RE, type Segment, attributed, hasPipefail, segmentsOf } from './chain'
import { signatureOf, toolErrorKind } from './friction'
import { inlineBodyOf, verdictOf } from './review'

export const MAX_EVENTS = 40 // source: own choice, events one turn record keeps (~120 bytes each, 5 KB): a turn that ran a test loop folds repeats (foldEvent); the rest are counted in eventsDropped
export const MAX_LIVE_FRICTIONS = 10 // source: own choice, friction rows of one turn record, like FRICTION_TOP/3 of a session's rows
const LABEL_CAP = 40 // source: own choice, characters of a test label

// source: the test and gate commands this repo's CI and README "Developing" name, plus the other
// runners the owner's projects use (pytest, bun, npm/pnpm/yarn, node --test, cargo, go, swift). A
// closed list, so "a test command" is one definition; a runner not in it is not seen (the
// outcome model says so).
const TESTS: readonly (readonly [RegExp, (m: RegExpExecArray) => string])[] = [
  [/(?:^|\s)(?:python3?\s+-m\s+)?pytest\b/, () => 'pytest'],
  [/\bbun\s+test\b/, () => 'bun test'],
  [/\b(?:npm|pnpm|yarn)\s+(?:run\s+)?test\b/, () => 'npm test'],
  [/\bnode\b[^|&;]*\s--test\b/, () => 'node --test'],
  [/\bclaude\s+plugin\s+test\b/, () => 'claude plugin test'],
  [/\bclaude\s+plugin\s+validate\b/, () => 'claude plugin validate'],
  [/\bcargo\s+test\b/, () => 'cargo test'],
  [/\bgo\s+test\b/, () => 'go test'],
  [/\bswift\s+test\b/, () => 'swift test'],
  [/\btsc\b[^|&;]*--noEmit\b/, () => 'tsc'],
  [/\bruff\s+(?:check|format\s+--check)\b/, () => 'ruff'],
  [/\bscripts\/(check[-_][\w.-]+)/, (m) => `gate:${m[1]}`],
  [/\bbuild-codex\.mjs\s+--check\b/, () => 'gate:build-codex'],
]

export const testLabel = (segment: string): string | null => {
  for (const [re, label] of TESTS) {
    const m = re.exec(segment)
    if (m !== null) return label(m).slice(0, LABEL_CAP)
  }
  return null
}

export type GitOperation = {
  commit?: { sha?: string; kind?: string }
  push?: { branch?: string }
  pr?: { number?: number; url?: string; action?: string }
}
export type BashResult = { isError?: boolean; deny?: string; text?: string; result?: unknown }

const gitOperationOf = (res: BashResult): GitOperation => {
  const r = typeof res.result === 'object' && res.result !== null ? (res.result as { gitOperation?: unknown }) : {}
  return typeof r.gitOperation === 'object' && r.gitOperation !== null ? (r.gitOperation as GitOperation) : {}
}

const resultText = (res: BashResult): string => {
  const r = typeof res.result === 'object' && res.result !== null ? (res.result as { stdout?: unknown }) : {}
  return `${res.text ?? ''}\n${typeof r.stdout === 'string' ? r.stdout : ''}`
}

// source: friction.ts BASH_EXIT, measured 2026-10-14 on 8 of 10 transcript tool errors: a Bash
// command that exits non-zero is an errored call whose text starts with this line. The typed Bash
// result carries no exit code (claude-code-tools Bash output: stdout, stderr, interrupted).
const EXIT_LINE = /^Exit code (\d+)/

// A test's exit status: true for 0, false for a non-zero exit, null when it cannot be read (an
// errored call without the exit line: interrupted, timed out, refused).
export const exitOk = (res: BashResult): boolean | null => {
  if (res.isError !== true) return true
  const m = EXIT_LINE.exec((res.text ?? '').trimStart())
  return m === null ? null : m[1] === '0'
}

const SHA = String.raw`[0-9a-f]{7,40}`
// source: git's own commit summary line, `[branch sha] subject` (git commit stdout).
const COMMIT_LINE = new RegExp(`^\\[[^\\]\\n]*?\\s(${SHA})\\]`, 'm')

const prNumber = (arg: string | undefined): { repo: string; n: string } | null => {
  if (arg === undefined) return null
  const url = /github\.com\/([\w.-]+\/[\w.-]+)\/pull\/(\d+)/.exec(arg)
  if (url !== null) return { repo: url[1]!, n: url[2]! }
  return /^#?(\d+)$/.test(arg) ? { repo: '', n: arg.replace('#', '') } : null
}

export const prKey = (repo: string, n: string): string => `${repo}#${n}`

// Two PR keys name the same pull request when their numbers agree and their repositories do, or one
// of them names none (the call said `gh pr merge 23`).
export const samePr = (a: string | undefined, b: string | undefined): boolean => {
  if (a === undefined || b === undefined) return false
  const [ar, an] = a.split('#')
  const [br, bn] = b.split('#')
  return an === bn && (ar === '' || br === '' || ar === br)
}

const repoFlag = (segment: string): string => /(?:--repo|-R)[ =]([\w.-]+\/[\w.-]+)/.exec(segment)?.[1] ?? ''

// The first positional argument after the verb (not a flag, not a flag's value): the PR number or URL.
const positional = (segment: string, verb: string): string | undefined => {
  const rest = segment.slice(segment.search(new RegExp(`\\b${verb}\\b`)) + verb.length)
  const tokens = rest.trim().split(/\s+/)
  for (let i = 0; i < tokens.length; i++) {
    const t = tokens[i]!
    if (/^-(?:b|F|R|t|B|r|a|l|m|M)$|^--(?:body|body-file|repo|title|base|reviewer|assignee|label|milestone)$/.test(t)) {
      i++
      continue
    }
    if (t.startsWith('-')) continue
    return t.replace(/^["']|["']$/g, '')
  }
  return undefined
}

export type BashCall = {
  command: string
  at: number
  agent?: string
  res: BashResult
  // The text of the file the command's --body-file names: a string read, null unreadable, undefined no file named.
  bodyFile?: string | null
}

const resetBack = (segment: string): number | undefined => {
  const m = /\bHEAD(?:~(\d+)|(\^+))/.exec(segment)
  if (m === null) return undefined
  return m[1] !== undefined ? Number(m[1]) : (m[2]?.length ?? 1)
}

const shasIn = (segment: string): string[] => (segment.match(new RegExp(`(?<![\\w-])${SHA}(?![\\w-])`, 'g')) ?? []).map((s) => s.toLowerCase())

// `segs`: the command's simple commands; `runners`: how many of them are test runs (decides whether a failure is attributable).
type Ctx = { base: { at: number; agent?: string }; op: GitOperation; text: string; call: BashCall; segs: Segment[]; runners: number }

const srcOf = (fromCommand: boolean, fromOp: boolean): EventSource => (fromCommand && fromOp ? 'both' : fromOp ? 'git-operation' : 'command')

// The exit status of segment `idx` when the call's single status can be attributed to it (chain.ts attributed).
const statusOf = (idx: number, ctx: Ctx): boolean | null => attributed(ctx.segs, idx, exitOk(ctx.call.res), ctx.runners, hasPipefail(ctx.call.command))

// A test or gate run of one segment, with its exit status (null when not attributable: a pipe, `||`, `;`, several runners).
const testEvent = (idx: number, label: string, ctx: Ctx): OutcomeEvent => ({ ...ctx.base, kind: 'test', src: 'command', label, ok: statusOf(idx, ctx) })

export const MAX_PR_KEY = 151 // source: GitHub limits, 39 characters of owner, 100 of repository, '/', '#', and up to 10 digits of number; a longer key names no pull request

const prOf = (arg: { repo: string; n: string } | null, segment: string): { pr?: string } => {
  const pr = arg === null ? undefined : prKey(arg.repo || repoFlag(segment), arg.n)
  return pr === undefined || pr.length > MAX_PR_KEY ? {} : { pr }
}

const createEvent = (s: string, ctx: Ctx): OutcomeEvent => {
  const { op, text } = ctx
  const found = prNumber(op.pr?.url) ?? prNumber(/https:\/\/github\.com\/[^\s]+\/pull\/\d+/.exec(text)?.[0]) ?? (op.pr?.number === undefined ? null : { repo: '', n: String(op.pr.number) })
  return { ...ctx.base, kind: 'pr-create', src: srcOf(true, op.pr?.action === 'created'), ...prOf(found, s), ok: true }
}

// source: gh's own confirmation of a merge ("Merged pull request #N", "Squashed and merged pull request
// #N", "Pull request #N was already merged"), the text a merge prints when it has merged.
const MERGED_TEXT = /\b(?:merged pull request|was already merged)\b/i

// A merge or close counts (ok true) when the call proves it: gitOperation says so, or the segment's
// exit status is the call's, the pull request is named, the merge is not queued (`--auto`), and the
// result text, when there is any, confirms a merge. Anything else is ok null: not proven, not refuted.
const mergeOrCloseEvent = (idx: number, s: string, ctx: Ctx): OutcomeEvent => {
  const merging = RE.merge.test(s)
  const arg = prNumber(positional(s, merging ? 'merge' : 'close')) ?? (ctx.op.pr?.number === undefined ? null : { repo: '', n: String(ctx.op.pr.number) })
  const agreed = ctx.op.pr?.action === (merging ? 'merged' : 'closed')
  const pr = prOf(arg, s)
  const queued = merging && /--(?:auto|disable-auto)\b/.test(s)
  const clean = statusOf(idx, ctx) === true && pr.pr !== undefined && !queued
  const text = ctx.text.trim()
  const ok = agreed || (clean && (!merging || text === '' || MERGED_TEXT.test(text))) ? true : null
  return { ...ctx.base, kind: merging ? 'pr-merge' : 'pr-close', src: srcOf(true, agreed), ...pr, ok }
}

// A review verdict, from the comment body: inline in the command, or the file the register read.
const verdictEvent = (s: string, ctx: Ctx): OutcomeEvent[] => {
  const body = ctx.call.bodyFile !== undefined ? ctx.call.bodyFile : inlineBodyOf(s)
  const pr = prOf(prNumber(positional(s, 'comment')), s)
  const v = body === null ? null : verdictOf(body)
  if (v !== null) return [{ ...ctx.base, kind: 'verdict', src: srcOf(true, ctx.op.pr?.action === 'commented'), ...pr, verdict: v.verdict, ...(v.head === undefined ? {} : { head: v.head }), ok: true }]
  return body === null ? [{ ...ctx.base, kind: 'verdict', src: 'command', ...pr, verdict: 'unknown', ok: true }] : []
}

const resetEvent = (s: string, ctx: Ctx): OutcomeEvent[] => {
  const back = resetBack(s)
  if (!/--(?:hard|soft|mixed|keep|merge)\b/.test(s) && back === undefined && shasIn(s).length === 0) return [] // an unstage, not a reset of commits
  const target = shasIn(s)[0] ?? (back === undefined ? 'head' : `head~${back}`)
  return [{ ...ctx.base, kind: 'reset', src: 'command', sha: target, ...(back === undefined ? {} : { back }), ok: true }]
}

const revertEvents = (s: string, ctx: Ctx): OutcomeEvent[] => {
  const shas = shasIn(s.slice(s.search(RE.revert)))
  const targets = shas.length > 0 ? shas : /\bHEAD\b/.test(s) ? ['head'] : []
  return targets.map((sha) => ({ ...ctx.base, kind: 'revert' as const, src: 'command' as const, sha, ok: true }))
}

const commitEvent = (s: string, ctx: Ctx): OutcomeEvent => {
  const sha = ctx.op.commit?.sha ?? COMMIT_LINE.exec(ctx.text)?.[1]
  const amended = ctx.op.commit?.kind === 'amended' || /--amend\b/.test(s)
  return { ...ctx.base, kind: 'commit', src: srcOf(true, ctx.op.commit !== undefined), ...(sha ? { sha: sha.toLowerCase() } : {}), ...(amended ? { label: 'amended' } : {}), ok: true }
}

// The state-changing events of one segment (a call that errored claims none of them).
const stateEvents = (idx: number, s: string, ctx: Ctx): OutcomeEvent[] => {
  if (RE.commit.test(s)) return [commitEvent(s, ctx)]
  if (RE.revert.test(s)) return revertEvents(s, ctx)
  if (RE.reset.test(s)) return resetEvent(s, ctx)
  if (RE.push.test(s)) return [{ ...ctx.base, kind: 'push', src: srcOf(true, ctx.op.push !== undefined), ok: true }]
  if (RE.create.test(s)) return [createEvent(s, ctx)]
  if (RE.merge.test(s) || RE.close.test(s)) return [mergeOrCloseEvent(idx, s, ctx)]
  return RE.comment.test(s) ? verdictEvent(s, ctx) : []
}

const runnerLabel = (text: string): string | null => (RE.comment.test(text) || RE.commit.test(text) ? null : testLabel(text))

// The events one Bash call shows, in command order. A call that errored shows only its test runs
// (their exit status is the point) and the version-control operations `gitOperation` confirms: which
// segment of a failed chain failed is not readable, so no other state change is claimed.
export const eventsOfBash = (call: BashCall): OutcomeEvent[] => {
  const { command, at, res } = call
  if (typeof command !== 'string' || res.deny !== undefined) return []
  const segs = segmentsOf(command)
  const runners = segs.filter((g) => runnerLabel(g.text) !== null).length
  const ctx: Ctx = { base: { at, ...(call.agent === undefined ? {} : { agent: call.agent }) }, op: gitOperationOf(res), text: resultText(res), call, segs, runners }
  const out: OutcomeEvent[] = []
  segs.forEach((seg, idx) => {
    const label = runnerLabel(seg.text)
    if (label !== null) out.push(testEvent(idx, label, ctx))
    else if (res.isError !== true) out.push(...stateEvents(idx, seg.text, ctx))
  })
  // A call whose segments showed no commit but whose result says one happened (a wrapper script).
  const sha = ctx.op.commit?.sha
  if (sha !== undefined && !out.some((e) => e.kind === 'commit')) out.push({ ...ctx.base, kind: 'commit', src: 'git-operation', sha: sha.toLowerCase(), ok: true })
  return out
}

const sameEvent = (a: OutcomeEvent, b: OutcomeEvent): boolean =>
  a.kind === b.kind && a.agent === b.agent && a.src === b.src && a.sha === b.sha && a.pr === b.pr && a.label === b.label && a.head === b.head && a.ok === b.ok && a.verdict === b.verdict && a.back === b.back

// One event added to a turn's list: a repeat of the last one is folded into its `n`, past MAX_EVENTS
// the event is counted in `dropped`.
export const foldEvent = (list: { events: OutcomeEvent[]; dropped: number }, e: OutcomeEvent): { events: OutcomeEvent[]; dropped: number } => {
  const last = list.events[list.events.length - 1]
  if (last !== undefined && sameEvent(last, e)) return { events: [...list.events.slice(0, -1), { ...last, n: (last.n ?? 1) + (e.n ?? 1) }], dropped: list.dropped }
  return list.events.length < MAX_EVENTS ? { events: [...list.events, e], dropped: list.dropped } : { events: list.events, dropped: list.dropped + 1 }
}

// The friction a tool call that did not run or failed shows, with the same closed rules as the
// transcript registry (friction.ts toolErrorKind). A plugin's refusal (`deny`) is a harness refusal; a
// Bash command's own non-zero exit is none. null: no friction. The signature is masked and normalised
// by the same function, so a live row and a transcript row of one event are one row.
export const liveFrictionOf = (tool: string, res: BashResult): { kind: FrictionKind; signature: string } | null => {
  if (res.deny !== undefined) return { kind: 'harness-refusal', signature: signatureOf(res.deny) }
  if (res.isError !== true) return null
  const text = res.text ?? ''
  const kind = toolErrorKind(tool, text)
  return kind === null ? null : { kind, signature: signatureOf(text) }
}

export const addFriction = (list: readonly LiveFriction[], f: { kind: FrictionKind; signature: string }): LiveFriction[] => {
  const at = list.findIndex((x) => x.kind === f.kind && x.signature === f.signature)
  if (at >= 0) return list.map((x, i) => (i === at ? { ...x, count: x.count + 1 } : x))
  return list.length < MAX_LIVE_FRICTIONS ? [...list, { ...f, count: 1 }] : [...list]
}

files.hooks/friction.ts:
// What got in the model's way, read from a finished session's transcript. Pure and total: any text
// goes in, rows come out, a line that is not JSON is skipped and counted, nothing throws.

import type { FrictionKind, FrictionRow } from '../types'

// OPERATIONAL DEFINITION (one rule per measure, written once, here). A friction is a transcript
// event that one of the closed rules below matches; whatever no rule matches is not a friction.
// Drawn from the owner's 10 latest transcripts (495 tool results, measured 2026-10-14): tool errors
// are rare (10), and 8 of them were a Bash command's own non-zero exit; hook events are
// `attachment` events named by `attachment.type`, and hook_success (thousands) is not one.

export const FRICTION_TOP = 30 // source: own choice, rows kept per session; the 10 measured sessions held 59 hook events in a few distinct signatures
export const FRICTION_RECURRING = 10 // source: own choice, rows of the recurring list kept in state; the brief and the pane show fewer
export const FRICTION_MIN_SESSIONS = 2 // source: own choice, one session is an incident, two is a pattern
export const SIGNATURE_CAP = 120 // source: spec of the registry, characters kept of a signature

export type Friction = { kind: FrictionKind; signature: string; count: number }

// source: transcripts measured 2026-10-14, `attachment.type` is the hook event's kind. hook_blocking_error
// 27 (all on Stop: 16 "Owned cleanup remains", 5 "CONTEXT SOFT CAP REACHED", 3 "subagent
// reflection(s) pending", 2 redaction gate, 1 checkpoint threshold), hook_non_blocking_error 17
// ("Plugin directory does not exist"), hook_cancelled 15. hook_success and the rest are no friction.
const HOOK_KINDS: Readonly<Record<string, FrictionKind>> = {
  hook_blocking_error: 'hook-block',
  hook_non_blocking_error: 'hook-error',
  hook_cancelled: 'hook-cancelled',
}

// source: the 2 harness refusals of the 10 measured tool errors: "PreToolUse:Bash hook error: ... Bash
// blocked: ..." and "Permission to use Bash with command ... has been denied."
const REFUSAL = /Blocked:|hook error|PreToolUse|denied|permission|not allowed/i
// source: Claude Code's own messages for a tool misused (Edit before Read, an Edit that matches
// nothing, a schema violation); none occurred in the 10 measured tool errors, so this rule is stated
// from the tools' messages, not from the sample.
const MISUSE = /File has not been read|String to replace not found|InputValidationError|unknown (parameter|param|argument|option|field)/i
// source: spec of the registry: an MCP tool's error, or any error that says the link failed.
const MCP_TEXT = /connection|timed out/i
// source: the 8 of 10 measured tool errors that were a Bash command's own failure began with this
// line, the command's output after it: that is the command's result, not the harness's. An output
// saying "Permission denied" is then the command's, not a refusal.
const BASH_EXIT = /^Exit code \d+$/

// The signature normalisation, in this order (spec): quoted strings, /paths, long hex runs, tool-use
// ids, numbers; then cut. The same event on another day, path or id is one signature.
const NORMALISE: readonly (readonly [RegExp, string])[] = [
  [/"[^"\n]*"|(?<!\w)'[^'\n]*'|`[^`\n]*`/g, '<Q>'],
  [/(?<![\w<>])~?\/[^\s"'`,;)\]}]+/g, '<PATH>'],
  [/\b[0-9a-f]{8,}\b/gi, '<HEX>'],
  [/\btoolu_\w+/g, '<ID>'],
  [/\b\d+(?:\.\d+)*\b/g, 'N'],
]

const firstLine = (text: string): string => text.split('\n').find((l) => l.trim() !== '') ?? ''

// source: the two harness refusals read in 2026-10-14 transcripts. "Permission to use Bash with command
// <the whole command, often several lines> has been denied." carries the command, so every denial was
// unique; "PreToolUse:Write hook error: [bash -c '<hook command>']: [decision-gate] BLOCKED: <path>
// would add 12 ... lines. A block ..." carries the hook's command line. Both are reduced before the
// generic rules to what repeats: the tool, and the gate's first sentence.
const DENIED = /^Permission to use (\S+) with command [\s\S]*? has been denied/
const HOOK_ERROR = /^(PreToolUse:\S+ hook error): \[[\s\S]*?\]: ([\s\S]*)$/
const reduced = (text: string): string => {
  const t = text.trim()
  const denied = DENIED.exec(t)
  if (denied !== null) return `Permission to use ${denied[1]} with command <CMD> has been denied`
  const hook = HOOK_ERROR.exec(t)
  if (hook === null) return firstLine(t).trim()
  const gate = hook[2]!.trim()
  const end = gate.search(/\.(\s|$)/)
  return `${hook[1]}: ${firstLine(end < 0 ? gate : gate.slice(0, end)).trim()}`
}

// source: review of PR #19 (privacy finding): a signature flows into the brief and from there into the
// Cortex aggregate memory, and tokens without quotes passed through it unmasked (a GitHub token after
// "token", an Anthropic key after "api_key=", an AWS secret after "export NAME="). This step runs FIRST,
// before every other rule, replacing with <SECRET>: (d) known prefixes, (b) Bearer/Basic values, (a) the value
// after = or : of a credential-named key, (e) and (f) below, (c) any 16+ run mixing letters and digits.
const SECRET = '<SECRET>'
const PREFIXED = /\b(?:ghp_|gho_|github_pat_|sk-ant-|sk-|xox[abp]-|AKIA|AIza)[A-Za-z0-9_\-+/=]{8,}/g
const SCHEME = /\b(Bearer|Basic)\s+\S+/gi
const KEYED = /([A-Za-z0-9_.-]*(?:token|key|secret|passw(?:or)?d|pwd|auth|credential|bearer|session)[A-Za-z0-9_.-]*["']?)(\s*=\s*|:\s+)("[^"\n]*"|'[^'\n]*'|[^\s,;"')\]}]+)/gi
// (e) a flag or header: a token starting `--`, `-` or `x-` whose name holds a sensitive word, whitespace, then a non-flag value (`--password hunter2`, `x-api-key abc`). The lookbehind keeps it at a token start, so `box-key` is not one.
const FLAG = /(?<![\w.-])((?:--|-|x-)[A-Za-z0-9_.-]*(?:token|key|secret|passw(?:or)?d|pwd|auth|credential|bearer|session)[A-Za-z0-9_.-]*)(\s+)(?!-)("[^"\n]*"|'[^'\n]*'|[^\s,;"')\]}]+)/gi
// (f) `password:hunter2`: a name ENDING in a sensitive word, then `:` with no space. `SessionStart:startup` ends in "Start", so it is untouched; a hook-event suffix as the value (`session:startup`) is not a secret.
const COLON = /([A-Za-z0-9_.-]*(?:token|key|secret|passw(?:or)?d|pwd|auth|credential|bearer|session))(:)(?!(?:startup|resume|clear|compact|start|end|stop)\b)("[^"\n]*"|'[^'\n]*'|[^\s,;"')\]}]+)/gi
const RUN = /[A-Za-z0-9_\-+/=]{16,}/g
// A path or a URL is not a secret (a later rule names paths); a hex run is a hash or an id, named <HEX>; a tool-use id is <ID>.
const spared = (token: string): boolean => token.startsWith('/') || token.startsWith('~/') || token.includes('://')
const mixed = (run: string): boolean => /[A-Za-z]/.test(run) && /\d/.test(run) && !/^[0-9a-f]+$/i.test(run) && !run.startsWith('toolu_')

export const maskSecrets = (text: string): string =>
  text
    .replace(PREFIXED, SECRET)
    .replace(SCHEME, `$1 ${SECRET}`)
    .replace(KEYED, `$1$2${SECRET}`)
    .replace(FLAG, `$1$2${SECRET}`)
    .replace(COLON, `$1$2${SECRET}`)
    .replace(/\S+/g, (token) => (spared(token) ? token : token.replace(RUN, (run) => (mixed(run) ? SECRET : run))))

export const signatureOf = (text: string): string => NORMALISE.reduce((s, [re, to]) => s.replace(re, to), reduced(maskSecrets(text))).slice(0, SIGNATURE_CAP)

const obj = (v: unknown): Record<string, unknown> | null => (typeof v === 'object' && v !== null && !Array.isArray(v) ? (v as Record<string, unknown>) : null)
const str = (v: unknown): string => (typeof v === 'string' ? v : '')

// A hook event's text: `blockingError` (a string, or the nested { blockingError, command } the engine
// writes), else `stderr`, else `content`; the first that says anything.
const hookText = (a: Record<string, unknown>): string => {
  const b = a.blockingError
  const candidates = [typeof b === 'string' ? b : str(obj(b)?.blockingError), str(a.stderr), str(a.content)]
  return candidates.find((t) => t.trim() !== '') ?? ''
}

// A cancelled hook says nothing; what identifies it is its event and its script (the command's last
// path component, so a plugin's folder or a user's name is not part of it).
const cancelledText = (a: Record<string, unknown>): string => {
  const words = str(a.command).trim().split(/\s+/)
  const word = words.find((w) => w.includes('/')) ?? words[0] ?? ''
  const script = word.replace(/["']/g, '').split('/').pop() ?? ''
  return `${str(a.hookName)}: ${script}${a.timedOut === true ? ' timed out' : ' cancelled'}`
}

const resultText = (content: unknown): string =>
  typeof content === 'string' ? content : Array.isArray(content) ? content.map((b) => str(obj(b)?.text)).join('\n') : ''

// The kind of a failed tool call, or null when it is none of the closed three.
export const toolErrorKind = (tool: string, text: string): FrictionKind | null => {
  if (tool === 'Bash' && BASH_EXIT.test(firstLine(text).trim())) return null
  if (REFUSAL.test(text)) return 'harness-refusal'
  if (MISUSE.test(text)) return 'tool-misuse'
  if (tool.startsWith('mcp__') || MCP_TEXT.test(text)) return 'mcp-failure'
  return null
}

type Found = { kind: FrictionKind; text: string }

// Lines worth a parse: the rest of a transcript is never a friction.
const CANDIDATE = /"hook_blocking_error"|"hook_non_blocking_error"|"hook_cancelled"|"tool_use"|"tool_result"/

// Every friction event of the transcript in order, and the candidate lines that did not parse.
const scan = (jsonl: string): { found: Found[]; skipped: number } => {
  const found: Found[] = []
  const names = new Map<string, string>()
  let skipped = 0
  for (const line of jsonl.split('\n')) {
    if (!CANDIDATE.test(line)) continue
    let event: Record<string, unknown> | null
    try {
      event = obj(JSON.parse(line))
    } catch {
      skipped += 1
      continue
    }
    if (event === null) continue
    const a = obj(event.attachment)
    const kind = event.type === 'attachment' && a !== null ? HOOK_KINDS[str(a.type)] : undefined
    if (a !== null && kind !== undefined) {
      found.push({ kind, text: kind === 'hook-cancelled' ? cancelledText(a) : hookText(a) })
      continue
    }
    const content = obj(event.message)?.content
    if (!Array.isArray(content)) continue
    for (const b of content) {
      const block = obj(b)
      if (block?.type === 'tool_use') names.set(str(block.id), str(block.name))
      else if (block?.type === 'tool_result' && block.is_error === true) {
        const text = resultText(block.content)
        const k = toolErrorKind(names.get(str(block.tool_use_id)) ?? '', text)
        if (k !== null) found.push({ kind: k, text })
      }
    }
  }
  return { found, skipped }
}

const order = (a: string, b: string): number => (a < b ? -1 : a > b ? 1 : 0)

// The frictions of a transcript grouped by (kind, signature), most frequent first, at most
// FRICTION_TOP, with the candidate lines skipped as malformed. The order is total (count, kind,
// signature), so two processes reading the same file write the same value.
export const frictionScan = (jsonl: string): { rows: Friction[]; skipped: number } => {
  const { found, skipped } = scan(typeof jsonl === 'string' ? jsonl : '')
  const grouped = new Map<string, Friction>()
  for (const f of found) {
    const signature = signatureOf(f.text)
    const key = `${f.kind}\u0000${signature}`
    const row = grouped.get(key)
    if (row === undefined) grouped.set(key, { kind: f.kind, signature, count: 1 })
    else row.count += 1
  }
  const rows = [...grouped.values()].sort((a, b) => b.count - a.count || order(a.kind, b.kind) || order(a.signature, b.signature))
  return { rows: rows.slice(0, FRICTION_TOP), skipped }
}

export const frictionsOf = (jsonl: string): Friction[] => frictionScan(jsonl).rows

// The rows that recur: in at least FRICTION_MIN_SESSIONS of the sessions given (one list per session),
// most sessions first, then most occurrences, at most FRICTION_RECURRING. A session counts a row once.
export const recurringFrictions = (perSession: readonly (readonly Friction[])[]): FrictionRow[] => {
  const by = new Map<string, FrictionRow>()
  for (const rows of perSession) {
    const seen = new Set<string>()
    for (const r of rows) {
      const key = `${r.kind}\u0000${r.signature}`
      const row = by.get(key) ?? { kind: r.kind, signature: r.signature, sessions: 0, count: 0 }
      row.count += r.count
      if (!seen.has(key)) row.sessions += 1
      seen.add(key)
      by.set(key, row)
    }
  }
  return [...by.values()]
    .filter((r) => r.sessions >= FRICTION_MIN_SESSIONS)
    .sort((a, b) => b.sessions - a.sessions || b.count - a.count || order(a.kind, b.kind) || order(a.signature, b.signature))
    .slice(0, FRICTION_RECURRING)
}

export const FRICTION_MAX_BYTES = 20 * 1024 * 1024 // source: own choice; the largest of the owner's transcripts measured 2026-10-14 was 4.9 MB (4911342 bytes)

// A transcript that will never be measured: its file is gone, or past FRICTION_MAX_BYTES. A fact about
// the path, the same for every process that writes it.
export type Unavailable = { unavailable: 'missing' | 'too-large' }

// What a stored frictions:<session> value says: its well-formed rows. An unavailable marker is a
// measured session with no rows; anything else (an older or a damaged value) is read as no rows too.
export const rowsOf = (v: unknown): Friction[] =>
  Array.isArray(v)
    ? v.filter((r): r is Friction => typeof r === 'object' && r !== null && typeof (r as Friction).kind === 'string' && typeof (r as Friction).signature === 'string' && Number.isFinite((r as Friction).count))
    : []

// The recurring rows over some sessions of the stored frictions (a session with none stored is not in it).
export const recurringOver = (stored: ReadonlyMap<string, readonly Friction[]>, sessions: Iterable<string>): FrictionRow[] =>
  recurringFrictions([...sessions].flatMap((s) => (stored.has(s) ? [stored.get(s)!] : [])))

export const isUnavailable = (v: unknown): v is Unavailable => {
  const u = typeof v === 'object' && v !== null ? (v as { unavailable?: unknown }).unavailable : undefined
  return u === 'missing' || u === 'too-large'
}

// A turn record's live frictions (events.ts liveFrictionOf, seen at `tool.call`) summed over a
// session's records into rows, in the order of the transcript rows (count, kind, signature).
export const liveRowsOf = (perTurn: readonly (readonly { kind: FrictionKind; signature: string; count: number }[] | undefined)[]): Friction[] => {
  const grouped = new Map<string, Friction>()
  for (const list of perTurn)
    for (const f of list ?? []) {
      const key = `${f.kind}\u0000${f.signature}`
      const row = grouped.get(key)
      if (row === undefined) grouped.set(key, { kind: f.kind, signature: f.signature, count: f.count })
      else row.count += f.count
    }
  return [...grouped.values()].sort((a, b) => b.count - a.count || order(a.kind, b.kind) || order(a.signature, b.signature)).slice(0, FRICTION_TOP)
}

// Two readings of one session's frictions (the live events and the transcript) as one: the same
// (kind, signature) is the same event seen twice, so the larger count stands, never the sum.
export const mergeFrictions = (a: readonly Friction[], b: readonly Friction[]): Friction[] => {
  const grouped = new Map<string, Friction>()
  for (const f of [...a, ...b]) {
    const key = `${f.kind}\u0000${f.signature}`
    const row = grouped.get(key)
    if (row === undefined || f.count > row.count) grouped.set(key, { ...f })
  }
  return [...grouped.values()].sort((x, y) => y.count - x.count || order(x.kind, y.kind) || order(x.signature, y.signature)).slice(0, FRICTION_TOP)
}

