// What the insights hand to Cortex: ONE aggregate memory over the newest finished sessions, which
// replaces itself (supersedes_id). One memory per session was dropped: Cortex merged two summaries of
// the same template into one memory of mixed numbers, which recall did not find (measured on the live
// Cortex 2026-10-14). Pure, so the register and the tests share it; the push itself (register.tsx)
// lives outside any hook that ends the session.

import type { TurnRecord } from '../types'
import { BRIEF_LINE_CAP, BRIEF_SESSIONS, composeBrief, mechanicalShare, windowOf, windowSessions } from './brief'
import { delegationStats } from './delegations'
import { type Friction, recurringOver } from './friction'
import { sessionModels } from './models'

// The aggregate's text over the finished sessions' records (the newest BRIEF_SESSIONS of them), or
// null when nothing is measured. composeBrief's header is replaced, its lines kept. `frictions`: the
// frictions measured, by session; the ones recurring over this window's sessions are in the text.
export const aggregateSummary = (records: readonly TurnRecord[], now: number, frictions: ReadonlyMap<string, readonly Friction[]> = new Map()): string | null => {
  const w = windowOf(records, BRIEF_SESSIONS)
  const body = composeBrief({
    delegations: delegationStats(w.records),
    models: sessionModels(w.records),
    mechanical: mechanicalShare(w.records),
    frictions: recurringOver(frictions, windowSessions(w.records)),
  })
  if (body === null) return null
  const header = `Self-calibration (zetetic-insights, last ${w.sessions} finished sessions, as of ${new Date(now).toISOString().slice(0, 10)}):`

  return [header, ...body.split('\n').slice(1)].map((l) => l.slice(0, BRIEF_LINE_CAP)).join('\n')
}

// Cortex's remember result as the plugin receives it: the handler's dict as structuredContent (the
// tool declares an outputSchema: Cortex mcp_server/handlers/remember_schema.py), or the same JSON in
// a text block.
export type RememberReply = { content: readonly unknown[]; isError: boolean; structuredContent?: unknown }
// head: the aggregate is now this memory. merged: Cortex folded the text into ANOTHER memory (not
// ours). rejected: the write gate refused it, so NOTHING is stored and no session is covered.
// cleared: our head is gone or was superseded by a memory we did not create (foreignId, named only,
// never adopted). failed: nothing changed, retried at the next start.
export type RememberOutcome =
  | { kind: 'head'; memoryId: number }
  | { kind: 'merged'; memoryId: number | null }
  | { kind: 'rejected'; reason: string }
  | { kind: 'cleared'; reason: string; foreignId: number | null }
  | { kind: 'failed'; failure: string }

const textOf = (content: readonly unknown[]): string =>
  content.map((b) => (typeof b === 'object' && b !== null && 'text' in b ? String((b as { text: unknown }).text) : '')).join(' ').trim()

const resultOf = (r: RememberReply): Record<string, unknown> | null => {
  if (typeof r.structuredContent === 'object' && r.structuredContent !== null) return r.structuredContent as Record<string, unknown>
  try {
    const parsed: unknown = JSON.parse(textOf(r.content))
    return typeof parsed === 'object' && parsed !== null ? (parsed as Record<string, unknown>) : null
  } catch {
    return null
  }
}

const idOf = (v: unknown): number | null => (Number.isSafeInteger(v) && (v as number) > 0 ? (v as number) : null)

// The reply shapes are Cortex's own: stored/superseded/merged (remember_response.py 69-123), the
// supersede rejections (remember_helpers.py 821-873), the write gate's rejection (write_gate.py 145-166).
export const rememberOutcome = (r: RememberReply): RememberOutcome => {
  if (r.isError) return { kind: 'failed', failure: textOf(r.content) || 'remember returned an error' }
  const o = resultOf(r)
  if (o === null) return { kind: 'failed', failure: 'remember reply not parsed' }
  const id = idOf(o.memory_id)
  if (o.stored === true && o.action === 'merged') return { kind: 'merged', memoryId: id }
  if (o.stored === true) return id === null ? { kind: 'failed', failure: 'remember stored without a memory_id' } : { kind: 'head', memoryId: id }
  const reason = String(o.reason ?? o.action ?? 'not stored')
  if (reason === 'supersede_target_not_found' || reason === 'invalid_supersedes_id') return { kind: 'cleared', reason, foreignId: null }
  if (reason === 'supersede_target_already_superseded') return { kind: 'cleared', reason, foreignId: idOf(o.current_superseded_by_id) }
  if (o.action === 'superseded_conflict') return { kind: 'cleared', reason, foreignId: idOf(o.current_head_id) }
  return { kind: 'rejected', reason }
}

files.hooks/review.ts:
// The review verdict a `gh pr comment` carries and where its body is: inline (`--body`, a heredoc), in
// a file (`--body-file`, `-F`, `$(cat file)`). Pure and total. The reviewer protocol posts the verdict
// as the first line of the body, which is what is required here: a verdict quoted in prose, or deeper
// in the body, is none.

import { RE, quotedEnd, segmentsOf } from './chain'

const SHA = String.raw`[0-9a-f]{7,40}`

// ZETETIC-REVIEW: APPROVE or REQUEST-CHANGES as the first line of the body (leading whitespace
// allowed), the head sha cited on the next non-empty line.
export const verdictOf = (body: string): { verdict: 'approve' | 'changes'; head?: string } | null => {
  const m = /^\s*ZETETIC-REVIEW:[ \t]*(APPROVE|REQUEST-CHANGES)\b[^\n]*(?:\n|$)((?:[ \t]*\n)*[^\n]*)/.exec(body)
  if (m === null) return null
  const head = new RegExp(`^[ \\t]*(?:head|sha|commit)?[: ]*(${SHA})\\b`, 'i').exec((m[2] ?? '').trimStart())?.[1]
  return { verdict: m[1] === 'APPROVE' ? 'approve' : 'changes', ...(head === undefined ? {} : { head: head.toLowerCase() }) }
}

// The text of the first heredoc in `text` (from the line after its opener to the delimiter line), null when none.
const heredocBody = (text: string): string | null => {
  const open = /<<-?\s*(["']?)([A-Za-z_][\w-]*)\1[^\n]*\n/.exec(text)
  if (open === null) return null
  const lines = text.slice(open.index + open[0].length).split('\n')
  const stop = lines.findIndex((l) => l.trim() === open[2])
  return (stop < 0 ? lines : lines.slice(0, stop)).join('\n')
}

// The value of a `--body`/`-b` flag on the command's first line: a quoted string (a `$(cat <<EOF` heredoc
// inside it is the body), or one word. null: the flag's value is not readable from the text (a variable).
const flagValue = (segment: string): string | null | undefined => {
  const first = segment.indexOf('\n') < 0 ? segment.length : segment.indexOf('\n')
  const flag = /(?:^|\s)(?:-b|--body)(?:=|\s+)/.exec(segment.slice(0, first))
  if (flag === null) return undefined
  const start = flag.index + flag[0].length
  const quote = segment[start]
  if (quote === '"' || quote === "'") {
    const end = quotedEnd(segment, start)
    const inner = segment.slice(start + 1, segment[end - 1] === quote && end - 1 > start ? end - 1 : end)
    return inner.startsWith('$(') ? heredocBody(inner) : inner
  }
  const word = /^\S*/.exec(segment.slice(start))?.[0] ?? ''
  return word.startsWith('$') ? null : word
}

// The body a `gh pr comment` segment carries in its own text: the flag's value, or the heredoc that
// `--body-file -` reads. null when the body is elsewhere (a file) or not readable (a variable).
export const inlineBodyOf = (segment: string): string | null => {
  const value = flagValue(segment)
  if (value !== undefined) return value
  return /(?:--body-file|-F)[ =]-(?:\s|$)/.test(segment) ? heredocBody(segment) : null
}

const unquote = (word: string): string => word.replace(/^["']|["']$/g, '')

// A review body kept in a file: `--body-file <path>`, `-F <path>` or `--body "$(cat <path>)"`. `path` is
// resolved through the `cd <dir> &&` that precede the comment (the register resolves what is still
// relative against the session cwd); null when a `cd` target is a variable or a glob, so the file cannot
// be located. `-` (the heredoc already in the command) is no file.
export type BodyFileRef = { path: string | null }
export const bodyFileOf = (command: string): BodyFileRef | null => {
  let dir = ''
  let known = true
  for (const seg of segmentsOf(command)) {
    if (!RE.comment.test(seg.text)) {
      const cd = /^cd\s+("[^"]+"|'[^']+'|\S+)$/.exec(seg.text)
      if (cd === null) continue
      const to = unquote(cd[1]!)
      if (/[$`~*?]/.test(to) || to === '-') known = false
      else dir = to.startsWith('/') ? to : dir === '' ? to : `${dir.replace(/\/+$/, '')}/${to}`
      continue
    }
    const line = seg.text.split('\n')[0]!
    const file = /(?:^|\s)(?:--body-file|-F)[ =]("[^"]+"|'[^']+'|\S+)/.exec(line)?.[1] ?? /\$\(\s*cat\s+("[^"]+"|'[^']+'|[^\s)]+)\s*\)/.exec(line)?.[1]
    if (file === undefined || file === '-') return null
    const path = unquote(file)
    if (path.startsWith('/') || path.startsWith('~')) return { path }
    return { path: known ? (dir === '' ? path : `${dir.replace(/\/+$/, '')}/${path}`) : null }
  }
  return null
}

files.hooks/paths.ts:
// Where `~/` lands on the machine a mod runs on. Pure: the engine follows `$` only inside the module
// that spells it, so each mod's register file reads the three variables and hands their values here.
//
// This file exists once per mod that expands `~/` (a mod cannot import a file from another mod: the
// engine refuses it, "outside the plugin's folder"), and every copy is byte-identical;
// scripts/check-shared.sh fails when one differs.

export type PathVars = { home: string | undefined; userProfile: string | undefined; configDir: string | undefined }
export type Placed = { path: string } | { reason: string }

const isSet = (value: string | undefined): value is string => value !== undefined && value !== ''
const trimmed = (dir: string): string => dir.replace(/[\\/]+$/, '')

// source: HOME is the home on macOS and Linux, USERPROFILE on Windows (cmd and PowerShell set it,
// not HOME); Node's os.homedir() reads them in that order on each platform. Unset in a sandbox: no
// place, said as such, never `/`.
export const homeOf = (vars: PathVars): Placed =>
  isSet(vars.home) ? { path: trimmed(vars.home) } : isSet(vars.userProfile) ? { path: trimmed(vars.userProfile) } : { reason: 'neither HOME nor USERPROFILE is set' }

// source: CLAUDE_CONFIG_DIR relocates the engine's `~/.claude` (plugins/, reference/, settings.json);
// without it the config directory is `<home>/.claude`.
export const configDirOf = (vars: PathVars): Placed => {
  if (isSet(vars.configDir)) return { path: trimmed(vars.configDir) }
  const home = homeOf(vars)

  return 'path' in home ? { path: `${home.path}/.claude` } : home
}

const CONFIG_PREFIX = '~/.claude'

// A path as the mods spell it: `~/.claude/...` is under the config directory, any other `~/...` under
// the home, anything else is already a place.
export const placePath = (vars: PathVars, path: string): Placed => {
  if (!path.startsWith('~/')) return { path }
  const isConfig = path === CONFIG_PREFIX || path.startsWith(`${CONFIG_PREFIX}/`)
  const base = isConfig ? configDirOf(vars) : homeOf(vars)
  if ('reason' in base) return { reason: `${path} has no place: ${base.reason}` }

  return { path: `${base.path}/${path.slice(isConfig ? CONFIG_PREFIX.length + 1 : 2)}` }
}

